# POST /api/sheets/{sheetId}/periods/generate — generate one period per calendar month from the from-date's month to
# the to-date's month, each from the first to the last day of its month and named yyyy-mm, each written as
# PERIOD_ADDED. A month whose name is already a period of the sheet, or whose days overlap one, is left out. A blank
# date takes the sheet's today. A date that is not yyyy-MM-dd, or a to-date before the from-date, is a 400 and writes
# nothing. Responds with how many were made.
validate:
  class: net.officefloor.hq.app.period.ValidateGeneratePeriods
  next: generate
generate:
  class: net.officefloor.hq.app.period.GeneratePeriods
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithGeneratedPeriods
# POST /api/sheets/{sheetId}/periods/generate-fy — generate the twelve monthly periods of a fiscal year exactly as
# generate does, from the first day of the sheet's fiscal start month (the fiscal-start-month setting, 1 unless set) in
# the year given (yyyy, the FY<yyyy> the fiscal year is named) to the last day of the eleventh month after it. A year
# that is not yyyy is a 400 and writes nothing. Responds with how many were made.
validate:
  class: net.officefloor.hq.app.period.ValidateGenerateFiscalYear
  next: generate
generate:
  class: net.officefloor.hq.app.period.GeneratePeriods
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithGeneratedPeriods
# POST /api/sheets/{sheetId}/periods — add a period: a name and a from and to date, both inclusive. An empty name,
# a date that is not yyyy-MM-dd, a to-date before the from-date, a name already on the sheet (case and outer spaces
# ignored) or dates overlapping another period of the sheet is a 400 and writes nothing. Responds 201 with the
# period as stored.
validate:
  class: net.officefloor.hq.app.period.ValidatePeriod
  next: check
check:
  class: net.officefloor.hq.app.period.CheckNewPeriod
  govern: [ transaction ]
  next: add
add:
  class: net.officefloor.hq.app.period.AddPeriod
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.period.RecordPeriodAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriodCreated
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: the from and to dates are yyyy-MM-dd (blank for the sheet's today), and the to-date is not before
 *  the from-date. */
public class ValidateGeneratePeriods {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody GeneratePeriodsRequest request,
            SheetRepository sheets, Out<GeneratePeriodsValues> values) throws InvalidPeriodException {
        String sheet = sheetId.trim();
        LocalDate from = date(request == null ? null : request.from(), "from", sheets, sheet);
        LocalDate to = date(request == null ? null : request.to(), "to", sheets, sheet);
        if (to.isBefore(from)) {
            throw new InvalidPeriodException("The to-date may not be before the from-date");
        }
        String by = request == null || request.by() == null ? "" : request.by().trim();
        values.set(new GeneratePeriodsValues(from, to, by));
    }

    private static LocalDate date(String text, String which, SheetRepository sheets, String sheet)
            throws InvalidPeriodException {
        if (text == null || text.isBlank()) {
            return sheets.today(sheet);
        }
        try {
            return LocalDate.parse(text.trim());
        } catch (DateTimeParseException e) {
            throw new InvalidPeriodException("The " + which + "-date must be a date yyyy-MM-dd");
        }
    }
}
package net.officefloor.hq.app.period;

import java.time.YearMonth;
import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Stores one period per calendar month from the from-date's month to the to-date's month, each running from the
 *  first to the last day of its month and named yyyy-mm, and writes each as PERIOD_ADDED. A month whose name is
 *  already a period of the sheet, or whose days overlap one, is left out. */
public class GeneratePeriods {
    public void generate(@PathVariable("sheetId") String sheetId, @Val GeneratePeriodsValues values,
            PeriodRepository periods, Audit audit, Out<GeneratedPeriods> generated) {
        String sheet = sheetId.trim();
        int made = 0;
        YearMonth last = YearMonth.from(values.to());
        for (YearMonth month = YearMonth.from(values.from()); !month.isAfter(last); month = month.plusMonths(1)) {
            String name = month.toString();
            if (periods.nameTaken(sheet, name) || periods.overlaps(sheet, month.atDay(1), month.atEndOfMonth())) {
                continue;
            }
            Period period = periods.add(sheet, name, month.atDay(1), month.atEndOfMonth(), null);
            audit.record("PERIOD_ADDED sheet=" + period.sheetId() + " by=" + values.by() + " period=" + period.name()
                    + " from=" + period.from() + " to=" + period.to());
            made++;
        }
        generated.set(new GeneratedPeriods(made));
    }
}
